#!/usr/bin/env node
// SPDX-License-Identifier: Apache-2.0
// scripts/check-test-scope-tier.mjs — generated by arbiter (anti-fake-green A4, INV-89 / INV-124).
//
// Test-scope ↔ tier integrity. Cross-checks every `required` test level declared in
// test-pyramid.json against the gate surface (scripts/check-all.mjs + any
// .github/workflows/*.yml + Makefile). A declared category that NO gate step executes is a
// silent false-green — "we run contract tests" with no CI tier that ever does. A level marked
// n/a (deferred — its rationale is enforced by check-test-pyramid) is exempt. Wiring is proven
// by an explicit category signal (test:<cat> / keyword step / runner) OR a broad no-path suite
// (`npm test`, `vitest run`, `pytest`, `go test ./...`) over a default test root.
// NO-DATA (no manifest, or no gate surface) is a SKIP.
//
// Usage: node scripts/check-test-scope-tier.mjs [--dir <path>] [--help]
// Exit codes (INV-53): 0=PASS/SKIP, 1=declared-but-unwired category, 2=ERROR (self).
import { existsSync, readFileSync, readdirSync } from 'node:fs'
import { join, resolve } from 'node:path'

const args = process.argv.slice(2)
if (args.includes('--help') || args.includes('-h')) {
  process.stdout.write(
    [
      'Usage: node scripts/check-test-scope-tier.mjs [--dir <path>]',
      '',
      'Test-scope ↔ tier integrity. Fails when a test category declared `required` in',
      'test-pyramid.json is wired into NO gate step (a check-all.mjs check or a CI',
      'workflow) — a silently-absent declared category is a false-green. A level marked',
      'n/a (deferred) is exempt. NO-DATA (no manifest / no gate surface) is a SKIP.',
      '',
      'Options:',
      '  --dir <path>   Root directory to scan (default: cwd)',
      '  --help, -h     Show this help and exit',
      '',
    ].join('\n'),
  )
  process.exit(0)
}

const dirIdx = args.indexOf('--dir')
const ROOT = dirIdx >= 0 && args[dirIdx + 1] ? resolve(args[dirIdx + 1]) : resolve(process.cwd())
const MANIFEST = join(ROOT, 'test-pyramid.json')

// Default test roots a broad, no-path runner executes wholesale. A required level with
// a glob rooted here is run by such a suite even without a category-named step.
const DEFAULT_ROOTS = new Set(['__tests__', 'tests', 'test', 'src', 'spec'])

// Ordered category vocabulary. nameRe identifies the category from the level name;
// signalRe proves it is invoked somewhere on the gate surface. Order = specific→generic
// so "Hardware Integration" → hardware and "CLI Integration" → integration.
const CATEGORIES = [
  { id: 'e2e', nameRe: /e2e|end[\s-]?to[\s-]?end/i, signalRe: /test:e2e|\be2e\b|playwright|cypress|selenium/i },
  // signal = specific contract-test forms, NOT bare `contract` (collides with the always-present
  // check-exit-code-contract.mjs reference on the gate surface → false WIRED, #1499).
  { id: 'contract', nameRe: /contract/i, signalRe: /test:contract|contract[ _-]?tests?|contract\/|\bpact\b/i },
  {
    id: 'performance',
    nameRe: /performance|\bperf\b|load|stress/i,
    signalRe: /test:perf|\bperf(ormance)?\b|\bk6\b|gatling|locust|\bjmeter\b/i,
  },
  {
    id: 'property',
    nameRe: /property|fuzz|generative/i,
    signalRe: /test:fuzz|test:property|\bproperty\b|fast-check|hypothesis|proptest|quickcheck/i,
  },
  {
    id: 'behavioral',
    nameRe: /behaviou?ral|\bbdd\b/i,
    signalRe: /test:behavioral|test:bdd|\bbehaviou?ral\b|\bbdd\b|cucumber/i,
  },
  {
    id: 'component',
    nameRe: /component/i,
    signalRe: /test:component|\bcomponent\b|testing-library|storybook/i,
  },
  {
    id: 'hardware',
    nameRe: /hardware|emulat|simulat/i,
    signalRe: /test:hardware|\bhardware\b|qemu|renode|\bjtag\b/i,
  },
  { id: 'integration', nameRe: /integration/i, signalRe: /test:integration|\bintegration\b|testcontainers/i },
  { id: 'unit', nameRe: /unit/i, signalRe: /test:unit|\bunit tests?\b|['"]unit['"]/i },
]

// A broad, no-path test runner that executes the whole default suite (no path filter).
const BROAD_SUITE_RE =
  /['"]npm['"]\s*,\s*\[\s*['"]test['"]\s*[\],]|['"]vitest['"]\s*,\s*['"]run['"]\s*\]|['"]pytest['"]\s*[\]),]|['"]go['"]\s*,\s*\[\s*['"]test['"]\s*,\s*['"]\.\/\.\.\.['"]|['"]cargo['"]\s*,\s*\[\s*['"]test['"]\s*\]/i

function readSafe(p) {
  try {
    return readFileSync(p, 'utf-8')
  } catch {
    return ''
  }
}

function collectGateSurface() {
  let text = ''
  for (const rel of ['check-all.mjs', join('scripts', 'check-all.mjs'), 'Makefile', 'makefile']) {
    const p = join(ROOT, rel)
    if (existsSync(p)) text += readSafe(p) + '\n'
  }
  const wfDir = join(ROOT, '.github', 'workflows')
  if (existsSync(wfDir)) {
    let entries = []
    try {
      entries = readdirSync(wfDir)
    } catch {
      entries = []
    }
    for (const name of entries) {
      if (/\.ya?ml$/i.test(name)) text += readSafe(join(wfDir, name)) + '\n'
    }
  }
  return text
}

function categoryFor(name) {
  for (const c of CATEGORIES) if (c.nameRe.test(name)) return c
  return null
}

function isDefaultRooted(globs) {
  if (!Array.isArray(globs)) return false
  return globs.some((g) => typeof g === 'string' && DEFAULT_ROOTS.has(g.split('/')[0]))
}

function fallbackSignal(name) {
  const word = (name.split(/\s+/).pop() || '').toLowerCase().replace(/[^a-z0-9]/g, '')
  if (word.length < 3) return /a^/
  return new RegExp(`test:${word}|\\b${word}\\b`, 'i')
}

function main() {
  if (!existsSync(MANIFEST)) {
    process.stdout.write('[check-test-scope-tier] SKIP — test-pyramid.json not found (NO-DATA)\n')
    // #2052: recognized marker so runCheck surfaces SKIP, not PASS, in the gate summary.
    process.stdout.write('[SKIP] test-pyramid.json not found (NO-DATA)\n')
    return 0
  }
  let manifest
  try {
    manifest = JSON.parse(readFileSync(MANIFEST, 'utf-8'))
  } catch (e) {
    process.stderr.write(
      `[check-test-scope-tier] ERROR — invalid test-pyramid.json: ${e?.message ?? e}\n`,
    )
    return 2
  }
  if (!Array.isArray(manifest.levels)) {
    process.stderr.write('[check-test-scope-tier] ERROR — manifest.levels must be an array\n')
    return 2
  }

  const gate = collectGateSurface()
  if (gate.trim() === '') {
    process.stdout.write(
      '[check-test-scope-tier] SKIP — no gate surface (check-all.mjs / workflows) found\n',
    )
    // #2052: recognized marker so runCheck surfaces SKIP, not PASS, in the gate summary.
    process.stdout.write('[SKIP] no gate surface (check-all.mjs / workflows) found\n')
    return 0
  }
  const broadSuite = BROAD_SUITE_RE.test(gate)

  const unwired = []
  let assessed = 0
  for (const level of manifest.levels) {
    if (!level || level.status !== 'required') continue
    assessed++
    const name = typeof level.name === 'string' ? level.name : String(level.id ?? '?')
    const cat = categoryFor(name)
    const signalRe = cat ? cat.signalRe : fallbackSignal(name)
    const explicit = signalRe.test(gate)
    const broadCovered = broadSuite && isDefaultRooted(level.globs)
    if (!explicit && !broadCovered) {
      unwired.push({ id: level.id ?? '?', name, cat: cat?.id ?? 'unknown' })
    }
  }

  if (unwired.length > 0) {
    process.stderr.write(
      '[check-test-scope-tier] FAIL — declared `required` test categor(ies) wired into NO gate ' +
        'tier (silent false-green):\n',
    )
    for (const u of unwired) {
      process.stderr.write(
        `    ${u.id} (${u.name}) [${u.cat}] — no check-all step or workflow runs it\n`,
      )
    }
    process.stderr.write(
      '  Fix: wire the category into a gate (a check-all step or CI job that runs its tests),\n' +
        '  or mark the level "n/a" in test-pyramid.json with a rationale if deliberately deferred.\n',
    )
    return 1
  }

  process.stdout.write(
    `[check-test-scope-tier] OK — ${assessed} required level(s) wired into a gate tier\n`,
  )
  return 0
}

try {
  process.exit(main())
} catch (e) {
  process.stderr.write(`[check-test-scope-tier] ERROR — ${e?.message ?? e}\n`)
  process.exit(2)
}
